import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BusinessUseCasesProps = Record<string, any>;

const BusinessUseCases: React.FC<BusinessUseCasesProps> = ({
  backgroundColor = "#080c16",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "3 AI Use Cases That Move The Needle",
  items = [
    "Build Your Operating System",
    "Remove Communication Bottlenecks",
    "24/7 Voice AI Agent"
  ],
  accentColor = "#00e5ff",
  textColor = "#ffffff",
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global scale factor for responsive design
  const s = Math.min(width, height);
  
  // Title Animation
  const titleStartFrame = 5;
  const titleProgress = spring({
    fps,
    frame: frame - titleStartFrame,
    config: { damping: 16, stiffness: 100 },
  });
  
  const titleOpacity = interpolate(titleProgress, [0, 1], [0, 1]);
  const titleY = interpolate(titleProgress, [0, 1], [50, 0]);

  // Line Animation Calculation
  const listStartFrame = 20;
  const staggeredFrames = 25;
  const lastItemFrame = listStartFrame + Math.max(1, items.length - 1) * staggeredFrames;
  
  // Connecting line scale
  const lineScale = interpolate(
    frame,
    [listStartFrame, lastItemFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <div 
        style={{ 
          display: "flex", 
          flexDirection: "column", 
          padding: `${height * 0.15}px ${width * 0.1}px`,
          width: "100%",
          height: "100%",
          boxSizing: "border-box",
          transition: "none"
        }}
      >
        {/* Title Section */}
        <h1 
          style={{
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            fontSize: s * 0.065,
            fontWeight: 700,
            color: textColor,
            margin: 0,
            marginBottom: height * 0.1,
            textShadow: `0 0 30px ${accentColor}40`,
            transition: "none",
            letterSpacing: "-0.02em"
          }}
        >
          {title}
        </h1>

        {/* Roadmap List Container */}
        <div style={{ position: "relative", display: "flex", flexDirection: "column", gap: height * 0.08, transition: "none" }}>
          
          {/* Vertical Connecting Line */}
          {items.length > 1 && (
            <div 
              style={{
                position: "absolute",
                left: (s * 0.07) / 2 - 2, // Centered perfectly behind the dots
                top: s * 0.035, // Start exactly center of first dot
                bottom: s * 0.035, // End exactly center of last dot
                width: 4,
                backgroundColor: accentColor,
                opacity: 0.6,
                boxShadow: `0 0 15px ${accentColor}`,
                transformOrigin: "top",
                transform: `scaleY(${lineScale})`,
                transition: "none",
                zIndex: 0
              }} 
            />
          )}

          {/* List Items */}
          {items.map((item, index) => {
            const itemStart = listStartFrame + index * staggeredFrames;
            
            // Dot Spring
            const dotProgress = spring({ 
              fps, 
              frame: frame - itemStart, 
              config: { damping: 14, stiffness: 120 } 
            });
            const dotScale = interpolate(dotProgress, [0, 1], [0.3, 1]);
            const dotOpacity = interpolate(dotProgress, [0, 1], [0, 1]);

            // Text Spring (slightly delayed from dot)
            const textProgress = spring({ 
              fps, 
              frame: frame - itemStart - 8, 
              config: { damping: 16, stiffness: 100 } 
            });
            const textOpacity = interpolate(textProgress, [0, 1], [0, 1]);
            const textY = interpolate(textProgress, [0, 1], [30, 0]);

            return (
              <div 
                key={index} 
                style={{ 
                  display: "flex", 
                  alignItems: "center", 
                  gap: width * 0.025,
                  transition: "none",
                  zIndex: 1
                }}
              >
                {/* Numbered Dot */}
                <div 
                  style={{
                    width: s * 0.07,
                    height: s * 0.07,
                    borderRadius: "50%",
                    backgroundColor: accentColor,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    flexShrink: 0,
                    opacity: dotOpacity,
                    transform: `scale(${dotScale})`,
                    boxShadow: `0 0 20px ${accentColor}80`,
                    transition: "none"
                  }}
                >
                  <span 
                    style={{ 
                      color: backgroundColor, // High contrast against the cyan background
                      fontSize: s * 0.035, 
                      fontWeight: 700,
                      transition: "none",
                      lineHeight: 1
                    }}
                  >
                    {index + 1}
                  </span>
                </div>

                {/* Text Content */}
                <div 
                  style={{
                    opacity: textOpacity,
                    transform: `translateY(${textY}px)`,
                    fontSize: s * 0.05,
                    fontWeight: 600,
                    color: textColor,
                    transition: "none",
                    letterSpacing: "-0.01em"
                  }}
                >
                  {item}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default BusinessUseCases;